import React, { useEffect, useState } from "react";
import { io } from "socket.io-client";

const API_URL =
    process.env.REACT_APP_API_URL ||
    "http://localhost:5005";


function AlertFeed() {

    const [alerts, setAlerts] = useState([]);
    const [connected, setConnected] = useState(false);


    useEffect(() => {

        const socket = io(API_URL, {
            transports: ["websocket", "polling"],
            withCredentials: true,
        });


        // ==============================
        // CONNECT
        // ==============================

        socket.on("connect", () => {

            console.log(
                "AlertFeed Socket.IO connected:",
                socket.id
            );

            setConnected(true);
        });


        // ==============================
        // DISCONNECT
        // ==============================

        socket.on("disconnect", (reason) => {

            console.log(
                "AlertFeed Socket.IO disconnected:",
                reason
            );

            setConnected(false);
        });


        // ==============================
        // REAL-TIME ALERT
        // ==============================

        socket.on("alert", (alert) => {

            console.log(
                "AlertFeed received alert:",
                alert
            );


            setAlerts((current) => {

                const key =
                    alert._id ||
                    `${alert.productID}-${alert.timestamp}`;


                const exists = current.some(
                    (item) => {

                        const itemKey =
                            item._id ||
                            `${item.productID}-${item.timestamp}`;

                        return itemKey === key;
                    }
                );


                if (exists) {
                    return current;
                }


                return [
                    alert,
                    ...current,
                ].slice(0, 50);

            });

        });


        // ==============================
        // LOAD HISTORY
        // ==============================

        fetch(`${API_URL}/api/alerts`)
            .then((response) => {

                if (!response.ok) {
                    throw new Error(
                        `HTTP ${response.status}`
                    );
                }

                return response.json();

            })
            .then((history) => {

                console.log(
                    "AlertFeed alert history:",
                    history
                );


                setAlerts((current) => {

                    const combined = [
                        ...history,
                        ...current,
                    ];


                    const unique = Array.from(
                        new Map(
                            combined.map((item) => {

                                const key =
                                    item._id ||
                                    `${item.productID}-${item.timestamp}`;

                                return [
                                    key,
                                    item,
                                ];

                            })
                        ).values()
                    );


                    unique.sort(
                        (a, b) =>
                            new Date(b.timestamp) -
                            new Date(a.timestamp)
                    );


                    return unique.slice(0, 50);

                });

            })
            .catch((error) => {

                console.error(
                    "Failed to load alert history:",
                    error
                );

            });


        // ==============================
        // CLEANUP
        // ==============================

        return () => {
            socket.disconnect();
        };

    }, []);


    return (
        <div>

            <div
                style={{
                    marginBottom: "15px",
                    fontSize: "13px",
                }}
            >
                <span
                    style={{
                        color: connected
                            ? "#45e0ca"
                            : "#ff5555",
                    }}
                >
                    ●
                </span>

                {" "}

                {connected
                    ? "Live"
                    : "Disconnected"}

            </div>


            {alerts.map((alert) => (

                <div
                    key={
                        alert._id ||
                        `${alert.productID}-${alert.timestamp}`
                    }
                    style={{
                        padding: "15px",
                        marginBottom: "10px",
                        border:
                            "1px solid #203541",
                        background:
                            "#0d1a24",
                    }}
                >

                    <strong>
                        {alert.productID}
                    </strong>


                    <div
                        style={{
                            marginTop: "5px",
                            color:
                                alert.status?.includes(
                                    "CRITICAL"
                                )
                                    ? "#ff5c6c"
                                    : "#45e0ca",
                        }}
                    >
                        {alert.status}
                    </div>


                    <div
                        style={{
                            marginTop: "8px",
                            color: "#8ea2b1",
                            fontSize: "13px",
                        }}
                    >
                        Torque: {alert.torque} Nm
                        {" | "}
                        Tool Wear: {alert.toolWear}
                        {" | "}
                        RPM: {alert.rotationalSpeed}
                    </div>

                </div>

            ))}

        </div>
    );
}


export default AlertFeed;
